def transform(grid):
    """Recolor background cells in any row or column containing a marker."""
    marker = 0 if 0 in grid[0] else 4
    bg = 8 if marker == 0 else 5
    active_rows = {r for r, row in enumerate(grid) if marker in row}
    active_cols = {c for c in range(len(grid[0])) if any(row[c] == marker for row in grid)}
    return [[3 if value == bg and (r in active_rows or c in active_cols) else value
             for c, value in enumerate(row)] for r, row in enumerate(grid)]

