def transform(grid):
    """Project background bands based on marker rows/columns and periodic mask."""
    # provisional candidate; geometry inferred from demos
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    marker = next(v for v in set(v for row in grid for v in row) if v != bg)
    h, w = len(grid), len(grid[0])
    # Marker signals define periodic horizontal/vertical bands of width 3,
    # while markers themselves remain intact.
    active_r = {r for r in range(h) if marker in grid[r]}
    active_c = {c for c in range(w) if any(row[c] == marker for row in grid)}
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg and (r in active_r or c in active_c):
                out[r][c] = 3
    return out

