def transform(grid):
    """Draw color-3 straight segments between collinear marker cells."""
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    markers = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg}
    out = [row[:] for row in grid]
    for r in range(h):
