def transform(grid):
    # Expand the central marker into symmetric diagonal rays, then continue
    # the four-step diagonal lattice beneath the wedge.
    row = grid[0]
    n = len(row)
    center = next(i for i, v in enumerate(row) if v == 2)
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if r >= 3 and (c - r - center) % 4 == 0:
                out[r][c] = 1
    for r in range(center + 1):
        for c in {center - r, center + r}:
            if 0 <= c < n:
                out[r][c] = 2
    return out

