def transform(grid):
    row = grid[0]
    n = len(row)
    center = next(i for i, value in enumerate(row) if value == 2)
    out = [[0] * n for _ in range(n)]

    # Expand the input 2 down-left and down-right to the left and right edges.
    for r in range(center + 1):
        for c in (center - r, center + r):
            if 0 <= c < n:
                out[r][c] = 2

    # Begin successive 1-colored diagonal rays every two rows,
    # shifting their starting point two columns left each time.
    r, c = 3, center - 1
    while r < n and c >= 0:
        rr, cc = r, c
        while rr < n and cc < n:
            if out[rr][cc] == 0:
                out[rr][cc] = 1
            rr += 1
            cc += 1
        r += 2
        c -= 2
    return out

def transform(grid):
    out = [row[:] for row in grid]
