def transform(grid):
    """Replace gaps between repeated alternating non-background markers with 2."""
    from collections import Counter

    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    h, w = len(grid), len(grid[0])
    for r in range(h):
        for c in range(1, w - 1):
            if grid[r][c] == background and grid[r][c - 1] != background and grid[r][c + 1] == grid[r][c - 1]:
                out[r][c] = 2
    for c in range(w):
        for r in range(1, h - 1):
            if grid[r][c] == background and grid[r - 1][c] != background and grid[r + 1][c] == grid[r - 1][c]:
                out[r][c] = 2
    return out

if __name__ == '__main__':
    assert transform([[4,6,4,6,4,6,4]]) == [[4,6,2,6,2,6,4]]
    assert transform([[1,9,1]]) == [[1,2,1]]
    assert transform([[1],[9],[1]]) == [[1],[2],[1]]
    assert transform([[5,7,5,7]]) == [[5,2,5,7]]
    assert transform([[5],[7],[5]]) == [[5],[2],[5]]
    test = [[5]*27 for _ in range(18)]
    for r, cols in [(5,[3,5]), (15,[10,12,14,16,18,20,22]), (17,[14,16,18])]:
        for c in cols: test[r][c] = 7
    result = transform(test)
    assert len(result) == 18 and all(len(row) == 27 for row in result)
    print(result)

