    claimed = set()
    for r in range(h - 1):
        for c in range(w - 1):
            block = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            if block <= occupied and not (block & claimed):
                for rr, cc in block:
                    out[rr][cc] = 1
                claimed |= block
