    # lower/left=3, and central/lower=2.
    for r, c in occupied - claimed:
        if r <= 1 and c >= 2:
            out[r][c] = 4
        elif c <= 1 and r >= 1:
            out[r][c] = 3
        else:
            out[r][c] = 2
    return out

