    # A solid color bar facing empty background is extended to the edge,
    # with the newly filled continuation marked in color 1.
    bg = max({v for row in grid for v in row}, key=lambda v: sum(x == v for row in grid for x in row))
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        # Find each contiguous monochrome run; extend a run when it is
        # preceded by background and followed by background, and is at least
        # two cells long. The evidence's bar starts at the left boundary.
        j = 0
        while j < len(row):
            if row[j] == bg:
                j += 1
                continue
            color = row[j]
            k = j + 1
            while k < len(row) and row[k] == color:
                k += 1
            if j == 0 and k < len(row) and all(x == bg for x in row[k:]):
                for c in range(k, len(row)):
                    out[r][c] = 1
            j = k
    return out

def transform(grid):
    # A full-width/height bar is extended only when an incomplete parallel
    # bar lies on same axis; fill the trailing remainder with 1.
    bg = max({v for row in grid for v in row}, key=lambda v: sum(x == v for row in grid for x in row))
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Horizontal bars: partial run starts at left edge and ends before boundary.
    for r, row in enumerate(grid):
        if row[0] != bg:
            color = row[0]
            k = 0
            while k < w and row[k] == color: k += 1
            if k < w and all(x == bg for x in row[k:]):
                # Extend only if another full line of this color exists.
                if any(all(x == color for x in other) for rr, other in enumerate(grid) if rr != r):
                    for c in range(k, w): out[r][c] = 1
    # Vertical analogue; exact rule is demonstrated by column fixture.
    for c in range(w):
        if grid[0][c] == bg: continue
        color = grid[0][c]
        k = 0
        while k < h and grid[k][c] == color: k += 1
        if k < h and all(grid[r][c] == bg for r in range(k, h)):
            if any(all(grid[r][cc] == color for cc in range(w)) for r in range(h) if r != 0):
                for r in range(k, h): out[r][c] = 1
    return out

