    # Interior 1 markers extend rightward as 4 then 1, stopping before the 2 rail.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    rows = [r for r in range(h) if grid[r][0] == 2]
    cols = [c for c in range(w) if grid[0][c] == 2]
    for r in rows:
        for c in range(1, w):
            if grid[r][c] == 8:
                out[r][c] = 1
    for c in cols:
        for r in range(1, h):
            if grid[r][c] == 8:
                out[r][c] = 1
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 1:
                # marker becomes 4, and the cells to its right are filled 1
                # until an original non-background object/rail interrupts.
                out[r][c] = 4
                for j in range(c + 1, w):
                    if grid[r][j] == 2:
