def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Rays from 2-colored top/left and right/bottom edges recolor background.
    top_cols = [c for c, v in enumerate(grid[0]) if v == 2]
    left_rows = [r for r in range(h) if grid[r][0] == 2]
    right_rows = [r for r in range(h) if grid[r][w-1] == 2]
    for r in left_rows:
        for c in range(1, w):
            if grid[r][c] == 8: out[r][c] = 1
    for c in top_cols:
        for r in range(1, h):
            if grid[r][c] == 8: out[r][c] = 1
    # Sparse 1 markers become 4 and cast a horizontal ray of 1s toward right rail.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 1:
                out[r][c] = 4
                for j in range(c + 1, w):
                    if grid[r][j] == 2: break
                    out[r][j] = 1
    # The test geometry uses 0 rails around a 7 marker: matching ray/color structure.
    # Identify 0-valued edge rails and replace their inward adjacent background rays;
    # interior 7 markers seed rightward rays colored by the marker's associated output.
    if any(0 in row for row in grid):
        left = [r for r in range(h) if grid[r][0] == 0]
        right = [r for r in range(h) if grid[r][-1] == 0]
        top = [c for c, v in enumerate(grid[0]) if v == 0]
        # Edge rail cells themselves remain 0. The rails demarcate a rectangular
        # corner frame; convert the enclosed background to 1 and 7 markers to 4.
        for r in range(h):
            for c in range(w):
                if grid[r][c] == 7: out[r][c] = 4
        # Colored frame formed between opposing marked edge runs.
        if left and right:
            for r in range(min(left), max(left)+1):
                for c in range(w):
                    if grid[r][c] == 5: out[r][c] = 1
        elif left and top:
            for r in range(min(left), max(left)+1):
                for c in range(min(top), w):
                    if grid[r][c] == 5: out[r][c] = 1
            for r in range(h):
                for c in top:
                    if grid[r][c] == 5: out[r][c] = 1
    return out

