def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    vals = {v for row in grid for v in row}
    bg = max(vals, key=lambda v: sum(row.count(v) for row in grid))
    # End markers on edges project their sparse motif color inward. Sparse
    # interior points become 4 and terminate an incoming projection ray.
    edge_color = next(v for v in vals if v != bg and any(row[0] == v or row[-1] == v for row in grid))
    points = [(r,c) for r in range(h) for c in range(w) if grid[r][c] not in (bg, edge_color)]
    motif_color = next((grid[r][c] for r,c in points), None)
    if motif_color is None:
        return out
    for r in range(h):
        if grid[r][0] == edge_color:
            for c in range(1,w):
                if grid[r][c] == motif_color:
                    out[r][c] = 4
                    break
                if grid[r][c] == bg: out[r][c] = motif_color
        if grid[r][w-1] == edge_color:
            for c in range(w-2,-1,-1):
                if grid[r][c] == motif_color:
                    out[r][c] = 4
                    break
                if grid[r][c] == bg: out[r][c] = motif_color
    for c in range(w):
        if grid[0][c] == edge_color:
            for r in range(1,h):
                if grid[r][c] == motif_color:
                    out[r][c] = 4
                    break
                if grid[r][c] == bg: out[r][c] = motif_color
        if grid[h-1][c] == edge_color:
            for r in range(h-2,-1,-1):
                if grid[r][c] == motif_color:
                    out[r][c] = 4
                    break
                if grid[r][c] == bg: out[r][c] = motif_color
    return out

