def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    colors = sorted(set(v for row in grid for v in row) - {bg})
    if len(colors) < 2:
        return out
    frame, mark = colors[0], colors[1]
    # A connected block of frame color on an outer edge spans a beam; for
    # each cell in that block, project inward along the perpendicular axis.
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != frame:
                c += 1
                continue
            e = c
            while e + 1 < w and grid[r][e+1] == frame:
                e += 1
            if r == 0 or r == h-1:
                step = 1 if r == 0 else -1
                for cc in range(c, e+1):
                    rr = r + step
                    while 0 <= rr < h:
                        if grid[rr][cc] == mark:
                            out[rr][cc] = 4
                        elif grid[rr][cc] == bg:
                            out[rr][cc] = mark
                        rr += step
            c = e + 1
    # For a frame-defined vertical corridor, marks initiate a horizontal ray.
    left = all(grid[r][0] == frame for r in range(h))
    right = all(grid[r][w-1] == frame for r in range(h))
    if left and right:
        for r in range(h):
            for c in range(1, w-1):
                if grid[r][c] == mark:
                    out[r][c] = 4
                    for cc in range(c+1, w-1):
                        if grid[r][cc] == bg:
                            out[r][cc] = mark
    # Large uniform regions bounded by an edge marker can be filled using
    # the isolated marker color; this is handled by edge-started components.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == mark and (r == 0 or c == 0 or r == h-1 or c == w-1):
                # Only fill contiguous interior cells in the row from marker.
                for cc in range(c+1, w):
                    if grid[r][cc] == bg:
                        out[r][cc] = mark
    return out

