def transform(grid):
    """Copy anomalous cells in each pane to matching positions in the other panes and below the horizontal divider."""
    h, w = len(grid), len(grid[0])
    # Identify regular single-color grid dividers.
    divval = None
    for v in {x for row in grid for x in row}:
        if any(all(x == v for x in row) for row in grid) and any(all(row[c] == v for row in grid) for c in range(w)):
            divval = v
            break
    rows = [r for r in range(h) if all(x == divval for x in grid[r])]
    cols = [c for c in range(w) if all(grid[r][c] == divval for r in range(h))]
    rh = (rows[0] if rows else h)  # vertical period from first panel height
    cw = cols[0] if cols else w
    # All divider rows/columns remain; each panel has a canonical motif pattern.
    # Source is top-left panel; anomalous non-background cells across all panels
    # are projected into every corresponding panel cell position.
    bg = next(v for v in {x for row in grid for x in row} if v != divval and sum(row.count(v) for row in grid) > h*w//2)
    panels_r = [0] + [r+1 for r in rows]
    panels_c = [0] + [c+1 for c in cols]
    out = [row[:] for row in grid]
    for pr in panels_r:
        for pc in panels_c:
            for r in range(pr, min(pr+rh, h)):
                for c in range(pc, min(pc+cw, w)):
                    # corresponding local position and non-background anomaly from any panel
                    lr, lc = r-pr, c-pc
                    val = None
                    for qr in panels_r:
                        for qc in panels_c:
